/* Demonstrates _exit(2) use within a child process and status collection */
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/wait.h>

#define CUSTOM_EXIT_STATUS 42

int main(void) {
    pid_t pid;
    int status;

    // Flush standard output buffer before forking to ensure text is visible
    fflush(stdout);

    pid = fork();

    if (pid == -1) {
        perror("fork");
        return 1;
    }

    if (pid == 0) {
        // Child process
        printf("Child process (PID %d) terminating immediately with status %d.\n", getpid(), CUSTOM_EXIT_STATUS);

        // Use _exit() to terminate without flushing stdio buffers or calling atexit handlers
        _exit(CUSTOM_EXIT_STATUS); 

        // Control never reaches here
    } else {
        // Parent process
        printf("Parent (PID %d) waiting for child (PID %d).\n", getpid(), pid);

        // Wait for the child process to terminate
        if (wait(&status) == -1) {
            perror("wait");
            return 2;
        }

        // Check and report the collected status
        if (WIFEXITED(status)) {
            int collected_status = WEXITSTATUS(status);
            printf("Parent collected exit status: %d.\n", collected_status);
            if (collected_status == CUSTOM_EXIT_STATUS) {
                return 0;
            }
        }
    }
    return 3;
}
